package br.com.livraria.book.model;
import jakarta.persistence.*; import java.util.ArrayList; import java.util.List; import com.fasterxml.jackson.annotation.JsonIgnore;
@Entity @Table(name="tb_categoria") public class Categoria { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=100) private String nome; @Column(length=250) private String descricao; @JsonIgnore @OneToMany(mappedBy="categoria") private List<Book> livros=new ArrayList<>(); public Categoria(){} public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getNome(){return nome;} public void setNome(String nome){this.nome=nome;} public String getDescricao(){return descricao;} public void setDescricao(String descricao){this.descricao=descricao;} public List<Book> getLivros(){return livros;} public void setLivros(List<Book> livros){this.livros=livros;} }
